        String siblingName = sibling.getName();
        if (siblingName.startsWith(FD_LAYOUT) && siblingName.length() > FD_LAYOUT.length()) {
            File candidate = new File(sibling, name);
            if (candidate.exists()) return true;
        }
    }
    return false;
}
```

