public static boolean hasLayoutVariations(File file) {
    File folder = file.getParentFile();
    if (folder == null) {
        return false;
    }
    String folderName = folder.getName();
    if (!folderName.equals("layout") && !folderName.startsWith("layout-")) {
        return false;
    }
    String name = file.getName();
    File res = folder.getParentFile();
    if (res == null) {
        return false;
    }
    File[] siblings = res.listFiles();
    if (siblings == null) {
        return false;
    }
    for (File sibling : siblings) {
        if (sibling == folder) {
            continue;
        }
        if (!sibling.isDirectory()) {
            continue;
        }
        String siblingName = sibling.getName();
        if ((siblingName.equals("layout") || siblingName.startsWith("layout-"))
                && new File(sibling, name).exists()) {
            return true;
        }
    }
    return false;
}
```

